using System.Globalization;
using Diaspora.Modules.Media.Domain.Enums;
using Diaspora.SharedKernel.Primitives;
using Diaspora.SharedKernel.Results;

namespace Diaspora.Modules.Media.Domain.ValueObjects;

/// <summary>
/// Where an object lives inside a bucket or container, as an opaque path.
/// <para>
/// Generated by this module, never accepted from a client, and never derived from a
/// client-supplied file name. That is the rule that makes path traversal structurally
/// impossible rather than defended against: there is no code path where user input reaches a
/// key.
/// </para>
/// <para>
/// The layout is <c>{kind}/{yyyy}/{MM}/{dd}/{assetId}/{purpose}.{ext}</c>. The date segments
/// exist because every object store degrades on a single flat prefix with millions of keys,
/// and because a retention job that must delete everything older than seven years wants a
/// prefix scan rather than a table scan. The asset id segment means every rendition of one
/// asset shares a folder, so deleting an asset is one prefix delete rather than a fan-out.
/// </para>
/// </summary>
public sealed class StorageKey : ValueObject
{
    public const int MaxLength = 512;

    private StorageKey(string value)
    {
        Value = value;
    }

    public string Value { get; }

    /// <summary>
    /// The prefix every rendition of one asset shares. Deleting an asset deletes this prefix.
    /// </summary>
    public string Prefix
    {
        get
        {
            var lastSlash = Value.LastIndexOf('/');
            return lastSlash < 0 ? string.Empty : Value[..lastSlash];
        }
    }

    /// <summary>Builds the key for an asset's original bytes.</summary>
    public static StorageKey ForOriginal(
        MediaKind kind, Guid assetId, FileExtension extension, DateTimeOffset createdAt) =>
        Build(kind, assetId, MediaVariantPurpose.Original, extension, createdAt);

    /// <summary>Builds the key for one derived rendition, alongside its original.</summary>
    public static StorageKey ForVariant(
        StorageKey original, MediaVariantPurpose purpose, FileExtension extension)
    {
        ArgumentNullException.ThrowIfNull(original);
        ArgumentNullException.ThrowIfNull(extension);

        var name = purpose.ToString().ToLowerInvariant();
        var suffix = extension.HasValue ? $".{extension.Value}" : string.Empty;

        return new StorageKey($"{original.Prefix}/{name}{suffix}");
    }

    /// <summary>
    /// Builds the key for one part of an in-flight chunked upload. Parts live under their own
    /// prefix so a sweep of expired sessions never has to distinguish them from real assets.
    /// </summary>
    public static StorageKey ForUploadPart(Guid sessionId, int chunkNumber) =>
        new(string.Create(
            CultureInfo.InvariantCulture,
            $"uploads/{sessionId:N}/part-{chunkNumber:D6}"));

    /// <summary>The prefix holding every part of one upload session.</summary>
    public static string UploadPrefix(Guid sessionId) =>
        string.Create(CultureInfo.InvariantCulture, $"uploads/{sessionId:N}");

    /// <summary>
    /// Rehydrates a key read back from the database. Validating rather than trusting, because
    /// a key that acquired a <c>..</c> segment through a bad migration must not be handed to a
    /// filesystem provider.
    /// </summary>
    public static Result<StorageKey> TryCreate(string? value)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            return Result.Failure<StorageKey>(Error.Validation(
                MediaErrorCodes.StorageObjectMissing, "A storage key is required."));
        }

        var normalized = value.Trim();

        if (normalized.Length > MaxLength || !IsSafe(normalized))
        {
            return Result.Failure<StorageKey>(Error.Validation(
                MediaErrorCodes.StorageObjectMissing, "That storage key is not usable."));
        }

        return Result.Success(new StorageKey(normalized));
    }

    public static StorageKey Create(string value) =>
        TryCreate(value) is { IsSuccess: true } result
            ? result.Value
            : throw new ArgumentException("Not a usable storage key.", nameof(value));

    public override string ToString() => Value;

    protected override IEnumerable<object?> GetEqualityComponents()
    {
        yield return Value;
    }

    private static StorageKey Build(
        MediaKind kind,
        Guid assetId,
        MediaVariantPurpose purpose,
        FileExtension extension,
        DateTimeOffset createdAt)
    {
        ArgumentNullException.ThrowIfNull(extension);

        var folder = kind.ToString().ToLowerInvariant();
        var name = purpose.ToString().ToLowerInvariant();
        var suffix = extension.HasValue ? $".{extension.Value}" : string.Empty;

        return new StorageKey(string.Create(
            CultureInfo.InvariantCulture,
            $"{folder}/{createdAt:yyyy}/{createdAt:MM}/{createdAt:dd}/{assetId:N}/{name}{suffix}"));
    }

    /// <summary>
    /// An allow-list. No traversal segments, no absolute paths, no backslashes, no control
    /// characters — every one of which means something different to S3, to Azure Blob and to a
    /// filesystem, and the intersection of "safe on all three" is narrow.
    /// </summary>
    private static bool IsSafe(string value)
    {
        if (value.StartsWith('/') || value.EndsWith('/') || value.Contains("//", StringComparison.Ordinal))
        {
            return false;
        }

        if (value.Split('/').Any(segment => segment is "." or ".." || segment.Length == 0))
        {
            return false;
        }

        return value.All(character =>
            char.IsAsciiLetterOrDigit(character) || character is '/' or '-' or '_' or '.');
    }
}
